int isspace(int ch)
{
	return (ch == '\r' || ch == '\n' || ch == ' ' || ch == '\t') ? 1 : 0;
}

int isdigit(int ch)
{
	return (ch >= '0' && ch <= '9') ? 1 : 0;
}

int isupper(int ch)
{
	return (ch >= 'A' && ch <= 'Z') ? 1 : 0;
}

int toupper(int ch)
{
	return (ch >= 'a' && ch <= 'z') ? ch - 'a' + 'A' : ch;
}

int tolower(int ch)
{
	return (ch >= 'A' && ch <= 'Z') ? ch - 'A' + 'a' : ch;
}

/*
 * add by chenxy
 */
int isxdigit(int ch)
{
	return ((ch >= '0' && ch <= '9')
			|| (ch >= 'a' && ch <= 'f')
			|| (ch >= 'A' && ch <= 'F')) ? 1 : 0;
}
int islower(int ch)
{
	return (ch >= 'a' && ch <= 'z') ? 1 : 0;
}

