unsigned int atoi(const char *str)
{
	const char *cp;
	unsigned int data = 0;

	if (str[0] == '0' && (str[1] == 'X' || str[1] == 'x'))
		return htoi(str + 2);

	for (cp = str, data = 0; *cp != 0; ++cp) {
		if (*cp >= '0' && *cp <= '9')
			data = data * 10 + *cp - '0';
		else
			break;
	}

	return data;
}

unsigned int htoi(const char *str)
{
	const char *cp;
	unsigned int data = 0, bdata = 0;

	for (cp = str, data = 0; *cp != 0; ++cp) {
		if (*cp >= '0' && *cp <= '9')
			bdata = *cp - '0';
		else if (*cp >= 'A' && *cp <= 'F')
			bdata = *cp - 'A' + 10;
		else if (*cp >= 'a' && *cp <= 'f')
			bdata = *cp - 'a' + 10;
		else
			break;
		data = (data << 4) | bdata;
	}

	return data;
}

/**
 * simple_strtoull - convert a string to an unsigned long long
 * @cp: The start of the string
 * @endp: A pointer to the end of the parsed string will be placed here
 * @base: The number base to use
 */
unsigned long long simple_strtoull(const char *cp,char **endp,unsigned int base)
{
	unsigned long long result = 0,value;

	if (!base) {
		base = 10;
		if (*cp == '0') {
			base = 8;
			cp++;
			if ((tolower(*cp) == 'x') && isxdigit(cp[1])) {
				cp++;
				base = 16;
			}
		}
	} else if (base == 16) {
		if (cp[0] == '0' && tolower(cp[1]) == 'x')
			cp += 2;
	}
	while (isxdigit(*cp)
	 && (value = isdigit(*cp) ? *cp-'0' : tolower(*cp)-'a'+10) < base) {
		result = result*base + value;
		cp++;
	}
	if (endp)
		*endp = (char *)cp;
	return result;
}

unsigned long simple_strtoul(const char *cp, char **endp,
                unsigned int base)
{
    unsigned long result = 0;
    unsigned long value;

    if (*cp == '0') {
        cp++;
        if ((*cp == 'x') && isxdigit(cp[1])) {
            base = 16;
            cp++;
        }

        if (!base)
            base = 8;
    }

    if (!base)
        base = 10;

    while (isxdigit(*cp) && (value = isdigit(*cp) ? *cp-'0' : (islower(*cp)
        ? toupper(*cp) : *cp)-'A'+10) < base) {
        result = result*base + value;
        cp++;
    }

    if (endp)
        *endp = (char *)cp;

    return result;
}

inline int putc(int ch)
{
	uart_compatible_putc(ch, CONFIG_UART_PORT);

	return 0;
}

int putchar(int ch)
{
	uart_compatible_putc(ch, CONFIG_UART_PORT);

	return 0;
}

int getchar(void)
{
	return uart_getc(CONFIG_UART_PORT);
}

inline int getc(void)
{
	return uart_getc(CONFIG_UART_PORT);
}

enum { GETSTR_ESCAPE = 0x01, GETSTR_APPEND = 0x02, GETSTR_APPENDDISP = 0x04 };

char *gets(char *str, int maxlen, int flag)
{
	int pos = 0;
	int ch;

	if (maxlen < 0)
		maxlen = 256;

	if (flag & GETSTR_APPEND) {
		while (str[pos] != 0) {
			if (flag & GETSTR_APPENDDISP)
				uart_compatible_putc(str[pos], CONFIG_UART_PORT);
			++pos;
		}
	}

	for (;;) {
		ch = uart_getc(CONFIG_UART_PORT);

		// escape sequence (0x1b, ...)
		if (ch == 0x1b) {
			if (flag & GETSTR_ESCAPE) {
				str[pos] = 0;
				return NULL;
			}
		}

		if (ch == 0x7f)	// DEL
			ch = '\b';
		else if (ch == '\n')
			ch = '\r';

		if (ch != '\b')
			uart_compatible_putc(ch, CONFIG_UART_PORT);
		if (ch == '\r') {
			uart_compatible_putc('\n', CONFIG_UART_PORT);
			break;
		}
		else if (ch == '\b') {
			if (pos > 0) {
				--pos;
				uart_compatible_putc(ch, CONFIG_UART_PORT);
				uart_compatible_putc(' ', CONFIG_UART_PORT);
				uart_compatible_putc(ch, CONFIG_UART_PORT);
			}
		}
		else {
			if (pos < maxlen - 2)
				str[pos++] = ch;
		}
	}

	str[pos] = 0;

	return str;
}

void puts(const char *t)
{
    while (*t) uart_compatible_putc(*t++, CONFIG_UART_PORT);
}

void putnstr( const char* str, int n)
{
	while (n && *str != '\0') {
		uart_compatible_putc(*str, CONFIG_UART_PORT);
		str++;
		n--;
	}
}

int fputc(int c, FILE * f)
{
	unsigned char ch = c;
#ifdef CONFIG_ENABLE_IO_FRAMEWORK
	return _fwrite(&ch, 1, f) == 1 ? ch : EOF;
#else
	uart_compatible_putc(ch, CONFIG_UART_PORT);
	return 0;
#endif
}

int printf(const char *fmt, ...)
{
#if CONFIG_PRINT_LEVEL >= 1
	char buf[1024];

	va_list args;
	int i;

	va_start(args, fmt);
	i = vsprintf(buf, fmt, args);	/* hopefully i < sizeof(buf) */
	va_end(args);

	puts(buf);

	return i;
#else
	return 0;
#endif
}

int vprintf(const char *fmt, va_list args)
{
#if CONFIG_PRINT_LEVEL >= 1
	uint i;
	char buf[1024];

	i = vsprintf(buf, fmt, args);	/* hopefully i < sizeof(buf) */

	/* Print the string */
	puts(buf);
	return i;
#else
	return 0;
#endif
}

#define GETCMD_MAXBUF       10
#define GETCMD_MAXLEN       512

char *readline(const char *prompt)
{
	static char s_cmdbuf[GETCMD_MAXBUF][GETCMD_MAXLEN];
	static int s_cmdnum = 0;
	static char str[GETCMD_MAXLEN];

	int i, ch, len, cmdpos = s_cmdnum;
	int flag = GETSTR_ESCAPE | GETSTR_APPEND;

	str[0] = 0;
	printf(prompt);

	while (gets(str, GETCMD_MAXLEN, flag) == NULL) {
		// get the escape sequence
		ch = getc();
		if (ch != 0x5b)
			continue;
		ch = getc();

		if (ch == 0x33) {
			ch = getc();
			continue;
		} else if (ch == 0x41) {	// up
			if (cmdpos == 0)
				continue;
			--cmdpos;
		} else if (ch == 0x42) {	// down
			if (cmdpos == s_cmdnum)
				continue;
			++cmdpos;
		} else
			continue;

		// clear line
		for (len = strlen(str); len > 0; --len) {
			putc('\b');
			putc(' ');
			putc('\b');
		}

		// redisplay line
		if (cmdpos == s_cmdnum)
			str[0] = 0;
		else {
			strcpy(str, s_cmdbuf[cmdpos]);
			puts(str);
		}
	}

	if (str[0] != 0) {
		// process '!' history
		if (str[0] == '!') {
			for (i = s_cmdnum - 1; i >= 0; --i)
				if (strncmp(s_cmdbuf[i], str + 1, strlen(str) - 1) == 0) {
					strcpy(str, s_cmdbuf[i]);
					break;
				}
		}
		// append new command
		if (s_cmdnum > 0 && strcmp(s_cmdbuf[s_cmdnum - 1], str) == 0) ;
		else if (s_cmdnum == GETCMD_MAXBUF) {
			for (i = 0; i < GETCMD_MAXBUF - 1; ++i)
				strcpy(s_cmdbuf[i], s_cmdbuf[i + 1]);
		} else
			++s_cmdnum;

		strcpy(s_cmdbuf[s_cmdnum - 1], str);
	}

	return str;
}

void perror(const char *msg)
{
	int errno = 0;
	printf("%s: error %d\n", msg, errno);
}

void exit(int status)
{
	return;
}

/* You can use " around spaces, but can't escape ". */
/* Hyphens and underscores equivalent in parameter names. */
char *next_arg(char *args, char **param, char **val)
{
	unsigned int i, equals = 0;
	int in_quote = 0, quoted = 0;
	char *next;

	if (*args == '"') {
		args++;
		in_quote = 1;
		quoted = 1;
	}

	for (i = 0; args[i]; i++) {
		if (args[i] == ' ' && !in_quote)
			break;
		if (equals == 0) {
			if (args[i] == '=')
				equals = i;
		}
		if (args[i] == '"')
			in_quote = !in_quote;
	}

	*param = args;
	if (!equals)
		*val = NULL;
	else {
		args[equals] = '\0';
		*val = args + equals + 1;

		/* Don't include quotes in value. */
		if (**val == '"') {
			(*val)++;
			if (args[i-1] == '"')
				args[i-1] = '\0';
		}
		if (quoted && args[i-1] == '"')
			args[i-1] = '\0';
	}

	if (args[i]) {
		args[i] = '\0';
		next = args + i + 1;
	} else
		next = args + i;

	/* Chew up trailing spaces. */
	while (*next == ' ')
		next++;
	return next;
}
